ControlPropertyState.AutoRuleBindingString:
Set(varBusy, true);
With(
    {
        uploadName: "capture-" & Text(Now(), "yyyymmddhhmmss") & ".jpg",
        uploadFolder: Text(Now(), "dd - mm - yyyy")
    },
    IfError(
        'EDS-UploadCaptureImage'.Run(
            {
                contentBytes: imgCapturePreview.Image,
                name: uploadName
            }
        );
        Notify("SharePointに保存しました", NotificationType.Success);
        Set(varBusy, false);
        Set(varCaptureTaken, false);
        Navigate(srcHome, ScreenTransition.None),
        Notify(
            "アップロードに失敗しました: " & Coalesce(FirstError.Message, "もう一度お試しください。"),
            NotificationType.Error
        );
        Set(varBusy, false)
    )
)
